--
-- Table structure for table `equipo`
--

DROP TABLE IF EXISTS `equipo`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `equipo` (
  `id_equipo` int NOT NULL AUTO_INCREMENT,
  `tipo_equipo` enum('pc','laptop','periferico','impresora','escaner','telefono','proyector','infraestructura','licencia','bien_control_admin','modem') NOT NULL COMMENT 'Discriminador tabla hija',
  `codigo_megan` varchar(120) DEFAULT NULL COMMENT 'Código contable MEGAN — editable',
  `codigo_sbye` varchar(120) DEFAULT NULL COMMENT 'Código SBAI/SBYE — editable',
  `descripcion` varchar(255) DEFAULT NULL,
  `marca` varchar(120) DEFAULT NULL,
  `modelo` varchar(200) DEFAULT NULL,
  `sn` varchar(150) DEFAULT NULL COMMENT 'Número de serie',
  `fecha_ingreso` date DEFAULT NULL,
  `costo` decimal(12,2) DEFAULT NULL,
  `estado` varchar(100) DEFAULT NULL,
  `observacion` text,
  `ultima_actualizacion` date DEFAULT NULL,
  `ultimo_mantenimiento` date DEFAULT NULL,
  `id_custodio_actual` int DEFAULT NULL,
  `id_ubicacion` int DEFAULT NULL,
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id_equipo`),
  KEY `idx_equipo_tipo` (`tipo_equipo`),
  KEY `idx_equipo_sbye` (`codigo_sbye`),
  KEY `idx_equipo_megan` (`codigo_megan`),
  KEY `idx_equipo_estado` (`estado`),
  KEY `idx_equipo_custodio` (`id_custodio_actual`),
  KEY `idx_equipo_ubicacion` (`id_ubicacion`),
  CONSTRAINT `fk_equipo_custodio` FOREIGN KEY (`id_custodio_actual`) REFERENCES `custodio` (`id_custodio`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `fk_equipo_ubicacion` FOREIGN KEY (`id_ubicacion`) REFERENCES `ubicacion` (`id_ubicacion`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1438 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Tabla padre: todos los activos tecnológicos DTIC';
/*!40101 SET character_set_client = @saved_cs_client */;

