--
-- Table structure for table `usuario`
--

DROP TABLE IF EXISTS `usuario`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `usuario` (
  `id_usuario` int NOT NULL AUTO_INCREMENT,
  `username` varchar(80) NOT NULL COMMENT 'Nombre de inicio de sesión',
  `password_hash` varchar(255) NOT NULL COMMENT 'Hash bcrypt/argon2 — nunca texto plano',
  `email` varchar(200) DEFAULT NULL,
  `rol` enum('ADMIN','TECNICO','CUSTODIO') NOT NULL COMMENT 'ADMIN=acceso total | TECNICO=edita nombre custodio | CUSTODIO=solo ve sus equipos',
  `id_custodio` int DEFAULT NULL COMMENT 'FK opcional: requerida para rol CUSTODIO, NULL para ADMIN/TECNICO',
  `activo` tinyint(1) NOT NULL DEFAULT '1',
  `creado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `actualizado_en` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `roles_extra` varchar(200) DEFAULT NULL COMMENT 'Roles adicionales separados por coma: ADMIN,TECNICO,CUSTODIO',
  PRIMARY KEY (`id_usuario`),
  UNIQUE KEY `uq_usuario_username` (`username`),
  UNIQUE KEY `uq_usuario_email` (`email`),
  KEY `idx_usuario_custodio` (`id_custodio`),
  KEY `idx_usuario_rol` (`rol`),
  CONSTRAINT `fk_usuario_custodio` FOREIGN KEY (`id_custodio`) REFERENCES `custodio` (`id_custodio`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=253 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='Cuentas de acceso al sistema con rol único por usuario';
/*!40101 SET character_set_client = @saved_cs_client */;

